 <div class="rekap-action-group"><a class="btn btn-outline-secondary btn-sm" href="rekap_nilai_import.php?pengajaran_id=<?= $pid ?>"><i class="fa-solid fa-file-import me-2" aria-hidden="true"></i>Impor Nilai</a><?php if($ready): ?><div class="dropdown"><button type="button" class="btn btn-outline-secondary btn-sm dropdown-toggle" data-bs-toggle="dropdown" aria-expanded="false"><i class="fa-solid fa-download me-2" aria-hidden="true"></i>Unduh Rekap</button><ul class="dropdown-menu dropdown-menu-end"><li><a class="dropdown-item" href="rekap_action.php?action=export_excel&amp;pengajaran_id=<?= $pid ?>"><i class="fa-solid fa-file-excel me-2" aria-hidden="true"></i>Unduh Excel</a></li><li><a class="dropdown-item" href="rekap_action.php?action=export_pdf&amp;pengajaran_id=<?= $pid ?>"><i class="fa-solid fa-file-pdf me-2" aria-hidden="true"></i>Unduh PDF</a></li></ul></div><?php endif ?></div>
</div>
<section class="nm-card rekap-results"><div class="rekap-table-heading"><div><h2>Daftar nilai siswa</h2><p><?= count($students) ?> siswa &middot; <?= count($components) ?> komponen penilaian</p></div><div class="rekap-table-help"><span><i class="fa-solid fa-circle-info me-1" aria-hidden="true"></i>Ubah nilai pada kolom yang tersedia, lalu klik Simpan.</span><span class="rekap-scroll-hint">Geser tabel untuk melihat semua komponen &harr;</span></div></div><form method="post" action="rekap_nilai_action.php"><?php $hidden('save_scores'); ?><div class="table-responsive rekap-table-scroll" tabindex="0" role="region" aria-label="Tabel nilai siswa, geser untuk melihat seluruh komponen"><table class="table align-middle mb-0"><caption class="visually-hidden">Rekap nilai siswa berdasarkan komponen dan bobot penilaian</caption><thead class="table-light"><tr><th scope="col">Siswa</th><?php foreach($components as $c): ?><th scope="col"><?= sanitize($c['nama_komponen']) ?><small class="d-block"><?= sanitize((string)$c['bobot']) ?>%</small></th><?php endforeach ?><th scope="col">Nilai Akhir</th></tr></thead><tbody><?php foreach($students as $s):$total=0;$complete=true; ?><tr><th scope="row" class="rekap-student"><?= sanitize($s['nama_lengkap']) ?></th><?php foreach($components as $c):$auto=$automatic[$s['id']][$c['nama_komponen']]??null;$override=isset($scores[$s['id']][$c['id']]);$value=$override?(float)$scores[$s['id']][$c['id']]:$auto;if($value===null)$complete=false;else $total+=$value*(float)$c['bobot']/100;$manual=$auto===null||$override; ?><td data-auto="<?= $auto!==null?number_format($auto,2,'.',''):'' ?>"><input type="hidden" class="score-source" name="sumber[<?= (int)$s['id'] ?>][<?= (int)$c['id'] ?>]" value="<?= $manual?'manual':'auto' ?>"><input class="form-control nm-score score-input" type="number" min="0" max="100" step="0.01" name="nilai[<?= (int)$s['id'] ?>][<?= (int)$c['id'] ?>]" aria-label="<?= sanitize($c['nama_komponen'].' '.$s['nama_lengkap']) ?>" value="<?= $value!==null?number_format($value,2,'.',''):'' ?>" <?= !$manual?'disabled':'' ?>><?php if($auto!==null): ?><span class="score-label small text-muted d-block mt-1"><?= $manual?'Manual':'Otomatis' ?></span><button type="button" class="score-toggle btn btn-link btn-sm px-0" aria-pressed="<?= $manual?'true':'false' ?>"><?= $manual?'Kembali ke Otomatis':'Isi Manual' ?></button><?php endif ?></td><?php endforeach ?><td class="rekap-final"><strong><?= $ready?($complete?number_format($total,2):'Belum lengkap'):'Bobot belum 100%' ?></strong></td></tr><?php endforeach ?><?php if(!$students): ?><tr><td colspan="<?= count($components)+2 ?>" class="text-center text-muted py-5">Belum ada siswa di kelas ini.</td></tr><?php endif ?></tbody></table></div><div class="rekap-save p-3 border-top"><span class="rekap-save-note"><i class="fa-solid fa-pen-to-square me-2" aria-hidden="true"></i>Setelah mengubah nilai, simpan perubahan Anda.</span><button class="btn btn-primary" <?= !$ready||!$students?'disabled':'' ?>><i class="fa-solid fa-check me-2" aria-hidden="true"></i>Simpan Perubahan Nilai</button></div></form></section>
